const mode = "direct";
if (!["direct", "relay"].includes(mode)) throw Error("Choose direct or relay mode");
return { json: { mode, event: $json } };

function map({ body, taskOrders, tags }) {
  if (
    body?.triggerId !== 12 ||
    body?.triggerName !== "taskDelayed" ||
    typeof body.taskId !== "string" ||
    !body.taskId
  )
    throw Error("Expected an Onfleet taskDelayed event");
  if (body.data?.task?.id && body.data.task.id !== body.taskId)
    throw Error("Onfleet task IDs disagree");
  if (!taskOrders || typeof taskOrders !== "object" || !Object.hasOwn(taskOrders, body.taskId))
    throw Error("Configure a Shopify order for this Onfleet task");
  const id = taskOrders[body.taskId];
  if (typeof id !== "string" || !/^gid:\/\/shopify\/Order\/\d+$/.test(id))
    throw Error("Configure the Shopify order GraphQL ID");
  if (
    !Array.isArray(tags) ||
    !tags.length ||
    tags.some((t) => typeof t !== "string" || !t.trim() || t.startsWith("YOUR_"))
  )
    throw Error("Configure replacement tags");
  const variables = { input: { id, tags } },
    query =
      "mutation UpdateOrder($input: OrderInput!){orderUpdate(input:$input){order{id} userErrors{field message}}}";
  return { variables, requestBody: { query, variables } };
}

const taskOrders = { YOUR_ONFLEET_TASK_ID: "gid://shopify/Order/YOUR_ORDER_ID" },
  tags = ["YOUR_REPLACEMENT_TAG"];
return { json: map({ body: $json.event, taskOrders, tags }) };

function confirm({ data, variables }) {
  const result = data?.data?.orderUpdate;
  if (
    !result ||
    !Array.isArray(result.userErrors) ||
    result.userErrors.length ||
    result.order?.id !== variables.input.id
  )
    throw Error("Shopify did not confirm the expected order update");
  return { confirmed: true };
}

return {
  json: confirm({
    data: $json,
    variables: $("Map task to order and replacement tags").item.json.variables,
  }),
};
